109	func runExport(ctx context.Context, cmd *cobra.Command, opts Options, exportOpts exportCommandOptions) error {
110		if exportOpts.checkpointLimit < 0 {
111			return errors.New("--checkpoint-limit must be greater than or equal to zero")
112		}
113		outputExplicit := exportOpts.outputExplicit || cmd.Flags().Changed("output")
114		if outputExplicit && strings.TrimSpace(exportOpts.outputDir) == "" {
115			return errors.New("--output must not be empty")
116		}
117		if strings.TrimSpace(exportOpts.entireBinary) == "" {
118			return errors.New("--entire-binary must not be empty")
119		}
120		if exportOpts.scope != exportScopeAll && exportOpts.scope != exportScopeBranch {
121			return errors.New("--scope must be either all or branch")
122		}
123	
124		repoDir, err := exportRepoDir(opts.Env)
125		if err != nil {
126			return err
127		}
128		if outputExplicit {
129			if _, err := validateExportDirAvailable(exportOpts.outputDir); err != nil {
130				return err
131			}
132		}
133	
134		var warnings []string
135		var selected map[string]selectedSession
136		var checkpointsScanned int
137		var snapshot *checkpointSnapshot
138	
139		reportExportStatus(exportOpts.progress, "detecting default branch")
140		defaultBranch, defaultBranchWarnings := detectDefaultBranch(ctx, opts.Runner, repoDir)
141		warnings = append(warnings, defaultBranchWarnings...)
142		reportExportStatus(exportOpts.progress, "mapping checkpoint branches")
143		branchDestinations, branchDestinationWarnings := buildCheckpointBranchDestinations(ctx, opts.Runner, repoDir, defaultBranch)
144		warnings = append(warnings, branchDestinationWarnings...)
145		reportExportStatus(exportOpts.progress, "reading checkpoint authors")
146		authorIndex, authorWarnings := buildCheckpointAuthorIndex(ctx, opts.Runner, repoDir)
147		warnings = append(warnings, authorWarnings...)
148	
149		if exportOpts.scope == exportScopeAll {
150			loadedSnapshot, snapshotWarnings, snapshotErr := loadConfiguredCheckpointSnapshot(ctx, opts.Runner, repoDir, exportOpts.rawTranscript, exportOpts.checkpointLimit, branchDestinations, exportOpts.progress)
151			if snapshotErr == nil {
152				snapshot = loadedSnapshot
153				defer snapshot.Cleanup()
154				selected = loadedSnapshot.Selected
155				checkpointsScanned = loadedSnapshot.CheckpointCount
156				warnings = append(warnings, snapshotWarnings...)
157				reportExportProgress(exportOpts.progress, checkpointsScanned, checkpointsScanned, len(selected))
158			} else if !errors.Is(snapshotErr, errCheckpointSnapshotUnavailable) {
159				warnings = append(warnings, "direct checkpoint export unavailable: "+snapshotErr.Error())
160			}
161		}
162	
163		if selected == nil {
164			checkpoints, discoverWarnings, err := discoverCheckpoints(ctx, opts.Runner, repoDir, exportOpts.entireBinary, exportOpts.scope, exportOpts.checkpointLimit)
165			if err != nil {
166				return err
167			}
168			warnings = append(warnings, discoverWarnings...)
169			checkpointsScanned = len(checkpoints)
170	
171			selected = make(map[string]selectedSession)
172			for i, checkpoint := range checkpoints {
173				reportExportProgress(exportOpts.progress, i+1, len(checkpoints), len(selected))
174				if !checkpoint.IsLogsOnly {
175					warnings = append(warnings, fmt.Sprintf("skipped non-committed checkpoint list entry %s", checkpoint.CheckpointID))
176					continue
177				}
178				if checkpoint.CheckpointID == "" {
179					warnings = append(warnings, "skipped checkpoint list entry with no checkpoint_id")
180					continue
181				}
182	
183				detail, detailErr := checkpointDetail(ctx, opts.Runner, repoDir, exportOpts.entireBinary, checkpoint.CheckpointID)
184				if detailErr != nil {
185					return detailErr
186				}
187	
188				for _, session := range detail.Sessions {
189					if session.Error != "" {
190						warnings = append(warnings, fmt.Sprintf("skipped checkpoint %s session %d: %s", detail.CheckpointID, session.Index, session.Error))
191						continue
192					}
193					if session.SessionID == "" {
194						warnings = append(warnings, fmt.Sprintf("skipped checkpoint %s session %d: missing session_id", detail.CheckpointID, session.Index))
195						continue
196					}
197	
198					createdAt := checkpoint.Date
199					if session.CreatedAt != nil && !session.CreatedAt.IsZero() {
200						createdAt = *session.CreatedAt
201					}
202	
203					candidate := selectedSession{
204						CheckpointID:     detail.CheckpointID,
205						SessionIndex:     session.Index,
206						SessionID:        session.SessionID,
207						Branch:           sessionBranch(session.Branch, detail.Branch),
208						Agent:            session.Agent,
209						Model:            session.Model,
210						Kind:             session.Kind,
211						ReviewSkills:     session.ReviewSkills,
212						CreatedAt:        createdAt,
213						TurnID:           session.TurnID,
214						IsTask:           session.IsTask,
215						ToolUseID:        session.ToolUseID,
216						FilesTouched:     session.FilesTouched,
217						TokenUsage:       session.TokenUsage,
218						Summary:          session.Summary,
219						CheckpointsCount: detail.CheckpointsCount,
220					}
221	
222					addSelectedSession(selected, candidate, branchDestinations)
223				}
224				reportExportProgress(exportOpts.progress, i+1, len(checkpoints), len(selected))
225			}
226		}
227	
228		manifest := exportManifest{
229			SchemaVersion:      1,
230			GeneratedAt:        opts.Now().UTC(),
231			RepoRoot:           repoDir,
